import numpy as np

def sigmoid(z):
    return 1.0 / (1.0 + np.exp(-np.asarray(z, dtype=float)))

def confusion(y_true, y_pred, threshold):
    '''Count TP/FP/FN/TN for probabilities with rule p >= threshold -> 1.'''
    y_true = list(y_true)
    y_pred = list(y_pred)
    if len(y_true) != len(y_pred):
        raise ValueError('y_true and y_pred must have the same length')
    tp = fp = fn = tn = 0
    for t, p in zip(y_true, y_pred):
        pred = 1 if float(p) >= threshold else 0
        if int(t) == 1 and pred == 1:
            tp += 1
        elif int(t) == 0 and pred == 1:
            fp += 1
        elif int(t) == 1 and pred == 0:
            fn += 1
        else:
            tn += 1
    return {'tp': tp, 'fp': fp, 'fn': fn, 'tn': tn}

def precision_recall_f1(cm):
    '''Return (precision, recall, f1); 0.0 where a denominator is zero.'''
    tp, fp, fn = cm['tp'], cm['fp'], cm['fn']
    precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
    recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
    if precision + recall > 0:
        f1 = 2 * precision * recall / (precision + recall)
    else:
        f1 = 0.0
    return (float(precision), float(recall), float(f1))

