import numpy as np
def __sig(z):
    return 1.0 / (1.0 + np.exp(-np.asarray(z, dtype=float)))
def __cm(y_true, y_pred, threshold):
    tp = fp = fn = tn = 0
    for t, p in zip(y_true, y_pred):
        pred = 1 if float(p) >= threshold else 0
        if int(t) == 1 and pred == 1:
            tp += 1
        elif int(t) == 0 and pred == 1:
            fp += 1
        elif int(t) == 1 and pred == 0:
            fn += 1
        else:
            tn += 1
    return {'tp': tp, 'fp': fp, 'fn': fn, 'tn': tn}
def __prf(cm):
    tp, fp, fn = cm['tp'], cm['fp'], cm['fn']
    precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
    recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
    f1 = 0.0 if precision + recall == 0 else 2 * precision * recall / (precision + recall)
    return (float(precision), float(recall), float(f1))
__check('sigmoid(0)=0.5', abs(float(np.asarray(sigmoid(0))) - 0.5) < 1e-12)
z = 2.0
__check('sigmoid wert', abs(float(np.asarray(sigmoid(z))) - float(__sig(z))) < 1e-9)
__check('symmetrie', abs(float(np.asarray(sigmoid(-1.7))) - (1 - float(np.asarray(sigmoid(1.7))))) < 1e-12)
yt, yp, t0 = [1, 0, 1, 0, 1, 0], [0.9, 0.8, 0.4, 0.3, 0.6, 0.2], 0.5
cm = confusion(yt, yp, t0)
__check('konfusion', dict(cm) == __cm(yt, yp, t0))
p, r, f = precision_recall_f1(cm)
wp, wr, wf = __prf(__cm(yt, yp, t0))
__check('precision', abs(p - wp) < 1e-9)
__check('recall', abs(r - wr) < 1e-9)
__check('f1', abs(f - wf) < 1e-9)
cm0 = confusion([0, 0], [0.1, 0.2], 0.5)
__check('nur TN', dict(cm0) == {'tp': 0, 'fp': 0, 'fn': 0, 'tn': 2})
__check('ohne positive', precision_recall_f1(cm0) == (0.0, 0.0, 0.0))
__check('grenze zaehlt als 1', dict(confusion([1], [0.5], 0.5)) == {'tp': 1, 'fp': 0, 'fn': 0, 'tn': 0})
__check('hoeherer schwellenwert', dict(confusion(yt, yp, 0.7)) == __cm(yt, yp, 0.7))

try:
    confusion([1, 0], [0.5], 0.5)
    __check('ValueError bei Laengen-Mismatch', False, 'kein ValueError')
except ValueError:
    __check('ValueError bei Laengen-Mismatch', True)
except Exception as e:
    __check('ValueError bei Laengen-Mismatch', False, type(e).__name__)

