expected.referenceSolver:
def subgroup_metrics(zaehlungen):
    fpr = {}
    selrate = {}
    for gruppe, z in zaehlungen.items():
        fpr[gruppe] = round(z["fp"] / (z["fp"] + z["tn"]), 3)
        selrate[gruppe] = round((z["tp"] + z["fp"]) / (z["tp"] + z["fp"] + z["fn"] + z["tn"]), 3)
    erste, zweite = sorted(zaehlungen)[:2]
    return {
        "fpr": fpr,
        "fpr_diff": round(abs(fpr[erste] - fpr[zweite]), 3),
        "selrate": selrate,
        "selrate_diff": round(abs(selrate[erste] - selrate[zweite]), 3),
    }

